const lastMessage = state.messages[state.messages.length - 1];
const userTask = typeof lastMessage.content === 'string' ? lastMessage.content : JSON.stringify(lastMessage.content);

const planPrompt = `You are an expert in task decomposition.
Define the team of specialists needed to accomplish the following task.

Task: ${userTask}

Return only the following JSON array (no explanation needed):
[
  {"name": "snake_case_role_name", "role": "description of the role", "task": "specific assigned task"},
  ...
]

Constraints:
- Define between 1 and 5 workers, only as many as needed for the task
- If one person can complete the task alone, assign only one worker
- name must be in snake_case English`;

const response = await model.invoke([{ role: 'user', content: planPrompt }]);
const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

let workerPlans;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  workerPlans = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  console.error('[planner] Failed to parse worker plans:', e);
  workerPlans = [{ name: 'general_worker', role: 'General handler', task: userTask }];
}

console.log(`[planner] Defined ${workerPlans.length} workers:`, JSON.stringify(workerPlans, null, 2));
return { workerPlans, messages: [response] };

const plan = state.currentPlan;
if (!plan) {
  console.error('[worker] No currentPlan in state');
  return { workerResults: [{ name: 'unknown', result: 'Error: no plan assigned' }] };
}

console.log(`[worker:${plan.name}] Starting task: ${plan.task}`);

const cwd = '/Users/akirakudo/Desktop/MyWork/test';
const workerPrompt = `You are an expert in ${plan.role}.

Assigned task: ${plan.task}

Working directory: ${cwd}
Always specify file paths as absolute paths (e.g., ${cwd}/src/formatDateJP.ts).
If you need to create or edit files or run commands, use the available tools (write_file, edit_file, bash_command, etc.) to actually execute them.
When running commands with bash_command, first cd ${cwd}.

Important constraints:
- Never use glob_files. File exploration is not needed.
- Use write_file or edit_file directly on the paths specified in the task.

Once all work is complete, report what you did in English.`;

const messages = [{ role: 'user', content: workerPrompt }];
let finalResult = '';

for (let i = 0; i < 10; i++) {
  const response = await model.invoke(messages);
  messages.push(response);

  const toolCalls = response.tool_calls || [];
  if (toolCalls.length === 0) {
    const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
    if (content && content.trim()) {
      finalResult = content;
    }
    break;
  }

  for (const toolCall of toolCalls) {
    console.log(`[worker:${plan.name}] Calling tool: ${toolCall.name}`);
    const tool = tools.find(t => t.name === toolCall.name);
    if (!tool) {
      console.error(`[worker:${plan.name}] Tool not found: ${toolCall.name}`);
      messages.push({ role: 'tool', tool_call_id: toolCall.id, content: `Error: tool ${toolCall.name} not found` });
      continue;
    }
    const toolResult = await tool.invoke(toolCall.args);
    const toolContent = typeof toolResult === 'string' ? toolResult : JSON.stringify(toolResult);
    messages.push(new ToolMessage({ tool_call_id: toolCall.id, content: toolContent }));
  }
}

console.log(`[worker:${plan.name}] Completed. Result preview: ${finalResult.slice(0, 100)}`);
return { workerResults: [{ name: plan.name, result: finalResult }], messages: [messages[messages.length - 1]] };

console.log(`[aggregator] Aggregating ${state.workerResults.length} worker results`);

const resultsSummary = state.workerResults.map(r => `## ${r.name}\n${r.result}`).join('\n\n');

const aggregatePrompt = `The following are the research and work results from each specialist team.

${resultsSummary}

Integrate these results to create a comprehensive final report in English.
Combine the contributions of each team member appropriately and organize the response to address the user's original request.`;

let finalReport = '';
for (let attempt = 0; attempt < 3; attempt++) {
  const response = await model.invoke([{ role: 'user', content: aggregatePrompt }]);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
  if (content && content.trim()) {
    finalReport = content;
    break;
  }
  console.warn(`[aggregator] Empty response on attempt ${attempt + 1}, retrying...`);
}

if (!finalReport) {
  console.warn('[aggregator] All attempts returned empty, falling back to worker results summary');
  finalReport = state.workerResults.map(r => `## ${r.name}\n${r.result || '(no result)'}`).join('\n\n');
}

console.log('[aggregator] Final report generated, length:', finalReport.length);
return { finalReport, messages: [{ role: 'assistant', content: finalReport }] };

console.log('[finalize] Teams workflow complete');
const report = (state.finalReport && state.finalReport.trim()) ? state.finalReport : (state.messages.slice().reverse().find(m => m.role === 'assistant' && m.content && m.content.trim())?.content) || 'No report generated';
return { messages: [{ role: 'assistant', content: report }] };
